const D = { energy: .6, scale: 1, density: .55, speed: 1, haze: .6, hue: 28, x: .5, y: .62, style: 'sodium', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- A container harbour at the bottom of the night. Four ranks of ship-to-shore gantries
// stand off into sodium haze, each rank drifting at its own incommensurate rate so the
// forest of legs opens and closes in parallax; trolleys crawl out along the booms and back,
// a ship stands at the quay, and the whole lit mass lies broken on the water. The subject is
// the haze and the sodium in it — the steel is only what interrupts the light. ----

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height), sd = P.seed|0;
function hsh(ix,iy){ let h=(Math.imul(ix,374761393)+Math.imul(iy,668265263)+Math.imul(sd,1442695041))|0;
  h=Math.imul(h^(h>>>13),1274126177)|0; return ((h^(h>>>16))>>>0)/4294967295; }   // >>> : a >> fold caps the hash at 0.5
function fr(i){ return hsh((i*7+13)|0, (i*31+5)|0); }
function vn(x,y){ const ix=Math.floor(x), iy=Math.floor(y), fx=x-ix, fy=y-iy;
  const wx=fx*fx*(3-2*fx), wy=fy*fy*(3-2*fy);
  const a=hsh(ix,iy), b=hsh(ix+1,iy), c=hsh(ix,iy+1), d=hsh(ix+1,iy+1);
  return a+(b-a)*wx+(c-a)*wy+(a-b-c+d)*wx*wy; }
function fbm(x,y){ return .55*vn(x,y)+.28*vn(x*2.03+5.1,y*2.03-3.3)+.17*vn(x*4.07-2.7,y*4.07+7.9); }
function hsv(h,s,v){ h=(((h%360)+360)%360)/60; const c=v*s, xx=c*(1-Math.abs(h%2-1)), m=v-c;
  let r,g2,b2;
  if(h<1){r=c;g2=xx;b2=0}else if(h<2){r=xx;g2=c;b2=0}else if(h<3){r=0;g2=c;b2=xx}
  else if(h<4){r=0;g2=xx;b2=c}else if(h<5){r=xx;g2=0;b2=c}else{r=c;g2=0;b2=xx}
  return [(r+m)*255,(g2+m)*255,(b2+m)*255]; }

const sty = P.style, en = cl(P.energy,0,1), hz = cl(P.haze,0,1);
const Hh = ((P.hue%360)+360)%360;
const tt = K.t;
const bp = sty==='blueprint', sil = sty==='silhouette', thm = sty==='thermal', dwn = sty==='dawn';

// ---- palette. skyT/skyH/hazeC as HSB triples; steel + lamp for the crisp pass ----
let skyT, skyH, hazeC, lampC, steelC, waterMul;
if (dwn)      { skyT=[Hh+188,26,44]; skyH=[Hh+6,30,84];  hazeC=[Hh+16,17,72]; lampC=[Hh+14,44,92]; steelC=[Hh+192,26,21]; waterMul=.74; }
else if (bp)  { skyT=[212,72,13];    skyH=[203,54,30];   hazeC=[200,46,38];   lampC=[188,58,98]; steelC=[190,70,86];  waterMul=.68; }
else if (thm) { skyT=[248,74,12];    skyH=[300,58,34];   hazeC=[318,48,44];   lampC=[44,88,99];  steelC=[262,54,26];  waterMul=.62; }
else if (sil) { skyT=[Hh+8,52,30];   skyH=[Hh+18,58,78]; hazeC=[Hh+16,40,62]; lampC=[Hh+20,30,96]; steelC=[Hh+200,30,7]; waterMul=.66; }
else          { skyT=[Hh+196,44,15]; skyH=[Hh+2,56,52];  hazeC=[Hh+8,42,44];  lampC=[Hh+6,72,99]; steelC=[Hh+200,28,12]; waterMul=.60; }

const wyn = cl(P.y,.35,.85);                 // waterline as a canvas fraction
const wy  = wyn*height;

// ---- perpetual pan: monotonic, guarded against a t0 reset (K.t can jump backwards) ----
if (S.pan == null) S.pan = 0;
if (S.lt == null || K.t < S.lt) S.lt = K.t;
const dt = cl(K.t - S.lt, 0, .1); S.lt = K.t;
S.pan += dt * P.speed * (.010 + .014*K.intensity) * (.8 + .2*Math.sin(tt*.047));
const pan = S.pan;

// ---- sky + cloud deck + water, into a coarse buffer -------------------------
const BW = 200, BH = Math.max(60, Math.round(BW*height/width));
if (!S.g || S.bk !== BW+'x'+BH){ if(S.g){ try{S.g.remove();}catch(e){} }
  S.g = createGraphics(BW,BH); S.g.pixelDensity(1); S.bk = BW+'x'+BH; }
const g = S.g; g.loadPixels(); const px = g.pixels;

const cTop = hsv(skyT[0], skyT[1]/100, skyT[2]/100);
const cHor = hsv(skyH[0], skyH[1]/100, skyH[2]/100);
const cHaz = hsv(hazeC[0], hazeC[1]/100, hazeC[2]/100);
const cLmp = hsv(lampC[0], lampC[1]/100, lampC[2]/100);
// cloud deck drifts on two incommensurate rates; the sodium glow breathes on a third
const cd1 = tt*.030, cd2 = tt*.019;
const glowB = (.42 + en*.62) * (.82 + .18*Math.sin(tt*.083) + .10*Math.sin(tt*.191+1.1) + K.swell*.10 + A.lowmid*.14);
const rip1 = tt*.61, rip2 = tt*1.43, rip3 = tt*2.29;

for (let j=0;j<BH;j++){
  const ny = (j+.5)/BH;
  for (let i=0;i<BW;i++){
    const nx = (i+.5)/BW;
    let r,g2,b2;
    if (ny < wyn){
      // --- sky: vertical ramp, cloud deck lit from below by the port, horizon glow ---
      const tv = Math.pow(cl(ny/wyn,0,1), 1.55);
      r = cTop[0]+(cHor[0]-cTop[0])*tv; g2 = cTop[1]+(cHor[1]-cTop[1])*tv; b2 = cTop[2]+(cHor[2]-cTop[2])*tv;
      // cloud deck: a real mass. It OCCLUDES the sky (darker) and its underside CATCHES the
      // sodium (brighter) — two-sided contrast is what makes it read, and what makes its
      // drift register on the motion gate. A lerp toward a near-identical haze colour moves
      // the numbers but shows nothing.
      const cf = fbm(nx*3.1 + cd1*3.0, ny*5.4 + cd2*1.7);
      const deck = cl((cf-.34)*2.6, 0, 1) * cl(1-ny/wyn*.30, 0, 1);
      const occ = deck*.44;
      r *= (1-occ); g2 *= (1-occ); b2 *= (1-occ);
      const lit = deck * (.30+glowB*.78) * (.28 + .72*Math.pow(cl(ny/wyn,0,1),1.6));
      r += cLmp[0]*lit*.60; g2 += cLmp[1]*lit*.60; b2 += cLmp[2]*lit*.60;
      // light pollution: a broad dome of sodium sitting on the horizon
      const dome = Math.exp(-(wyn-ny)*(5.2 - hz*2.4)) * (.30 + glowB*.50) * (.45+hz*.75);
      r += cLmp[0]*dome*.34; g2 += cLmp[1]*dome*.34; b2 += cLmp[2]*dome*.34;
    } else {
      // --- water: the sky mirrored, compressed and torn by ripple bands ---
      const dw = (ny-wyn)/Math.max(.03,1-wyn);          // 0 at the waterline, 1 at the near edge
      const rp = (fbm(nx*7.0 + rip2*.10, ny*46 - rip1*.9)-.5)*(.016+dw*.115)
               + Math.sin(ny*150*(1+dw*1.4) - rip3*.9 + nx*3.1)*(.0022+dw*.0165);
      const my = cl(wyn - (ny-wyn)*(.36+dw*.30) + rp, 0, wyn);
      const tv = Math.pow(cl(my/wyn,0,1), 1.55);
      r = cTop[0]+(cHor[0]-cTop[0])*tv; g2 = cTop[1]+(cHor[1]-cTop[1])*tv; b2 = cTop[2]+(cHor[2]-cTop[2])*tv;
      const dome = Math.exp(-(wyn-my)*(5.2-hz*2.4)) * (.30+glowB*.50) * (.45+hz*.75);
      r += cLmp[0]*dome*.34; g2 += cLmp[1]*dome*.34; b2 += cLmp[2]*dome*.34;
      // Fresnel: mirror-bright at the horizon, dark and dead underfoot
      const fres = waterMul * (1 - dw*.62);
      r *= fres; g2 *= fres; b2 *= fres;
      // chop catching the sodium — a BROAD live area element. This is what carries the motion
      // floor across ~38% of the frame when the port itself is quiet (see W3 failure mode 3:
      // fine detail alone contributes ~0.0003 and fails).
      const ch = Math.pow(cl(fbm(nx*13 + rip1*.5, ny*70 - rip2*.7), 0, 1), 2.2);
      const sp = ch*(.10+dw*.44)*(.30+en*.95);
      r += cLmp[0]*sp*.85; g2 += cLmp[1]*sp*.85; b2 += cLmp[2]*sp*.85;
    }
    const o = 4*(j*BW+i);
    px[o]=cl(r,0,255); px[o+1]=cl(g2,0,255); px[o+2]=cl(b2,0,255); px[o+3]=255;
  }
}
g.updatePixels();
push();
if (P.alpha<100) tint(0,0,100,P.alpha);
image(g,0,0,width,height);
pop();

// ---- the steel: four ranks receding into haze -------------------------------
const AL = P.alpha/100;
// aerial perspective: a plane at depth d fades toward the haze colour
function planeCol(base, d, lift){
  const k = cl(d*d*(.30+hz*.95), 0, .92);
  return [ base[0]+(hazeC[0]-base[0])*k, base[1]+(hazeC[1]-base[1])*k,
           base[2]+(hazeC[2]-base[2])*k*1.0 + lift*(1-k) ];
}
function sstroke(c, w, a){ stroke(c[0], c[1], c[2], a*AL); strokeWeight(Math.max(.6, w)); }

// one ship-to-shore gantry, drawn in screen space
function gantry(cx, base, h, c, lw, det, tro){
  const w = h*.62, legT = h*.16;
  const boomY = base - h*.86, apex = base - h*1.06;
  const seaX = cx - w*1.62*det, landX = cx + w*.72;
  sstroke(c, lw, 92);
  noFill();
  // portal legs (A-framed, sitting on the quay)
  line(cx-w*.5, base, cx-w*.5+legT*.22, boomY);
  line(cx+w*.5, base, cx+w*.5-legT*.22, boomY);
  line(cx-w*.5+w*.16, base, cx-w*.5+w*.16+legT*.10, boomY);
  line(cx+w*.5-w*.16, base, cx+w*.5-w*.16-legT*.10, boomY);
  // sill + portal beam
  sstroke(c, lw*1.5, 92);
  line(cx-w*.62, boomY, cx+w*.62, boomY);
  // the boom: out over the water, plus the landward backreach
  sstroke(c, lw*1.7, 94);
  line(seaX, boomY - h*.05, landX, boomY - h*.02);
  sstroke(c, lw*.8, 70);
  line(seaX, boomY + h*.055, landX, boomY + h*.03);       // lower chord -> the boom has depth
  // apex pylon + stays
  sstroke(c, lw, 84);
  line(cx-w*.30, boomY, cx, apex); line(cx+w*.30, boomY, cx, apex);
  line(cx, apex, seaX + h*.10, boomY - h*.05);            // seaward stay
  line(cx, apex, landX - h*.04, boomY - h*.02);           // landward stay
  if (det > .5){
    // boom lattice — the texture that makes it read as steel, not a rectangle
    sstroke(c, lw*.5, 46);
    const nb = 11;
    for (let i2=0;i2<nb;i2++){
      const q0 = i2/nb, q1 = (i2+1)/nb;
      const x0 = seaX+(landX-seaX)*q0, x1 = seaX+(landX-seaX)*q1;
      const yA = boomY-h*.05+(h*.03)*q0, yB = boomY+h*.055-(h*.025)*q1;
      line(x0, yA, x1, yB);
    }
  }
  // trolley: crawls the boom and back, forever, on its own rate
  const tx = seaX + (landX-seaX)*tro;
  const ty = boomY - h*.02;
  sstroke(c, lw*.8, 90);
  const hoist = h*(.16 + .30*(.5+.5*Math.sin(tro*7.4+cx*.01)));
  line(tx, ty, tx, ty+hoist);                              // hoist rope
  noStroke(); fill(c[0], c[1], Math.min(100,c[2]*1.5+8), 92*AL);
  rect(tx-h*.035, ty-h*.028, h*.07, h*.05);                // trolley
  rect(tx-h*.055, ty+hoist, h*.11, h*.022);                // spreader
  return { boomY: boomY, seaX: seaX, tx: tx, ty: ty };
}

// container stack
function stack(x0, base, cw, chh, cols, rows, c, lift, idb){
  noStroke();
  for (let cxi=0; cxi<cols; cxi++){
    const hR = 1 + Math.floor(fr(idb+cxi*3)*rows);
    for (let ri=0; ri<hR; ri++){
      const q = fr(idb+cxi*7+ri*13);
      const sh = 1 - ri*.05;
      fill(c[0] + (q-.5)*26, cl(c[1]*(.5+q*1.0),0,96), cl((c[2]+lift)*(.62+q*.85)*sh,0,96), 94*AL);
      rect(x0+cxi*cw, base-(ri+1)*chh, cw*.94, chh*.92);
    }
  }
}

const nearY = wy;
const dens = cl(P.density,0,1);
const sc = cl(P.scale,.5,2.2);
// four ranks: far -> near. Each drifts at its own incommensurate rate (true parallax).
const RANKS = [
  { d:.95, h:.055, y:-.004, rate:.16, n:Math.round(5+dens*7),  det:0, lw:.7 },
  { d:.66, h:.115, y: .008, rate:.42, n:Math.round(3+dens*4),  det:0, lw:.9 },
  { d:.34, h:.235, y: .030, rate:1.0, n:Math.round(2+dens*2),  det:1, lw:1.3 },
  { d:.10, h:.430, y: .072, rate:2.1, n:Math.round(1+dens*1),  det:1, lw:1.9 }
];

function drawSteel(){
  for (let ri=0; ri<RANKS.length; ri++){
    const R = RANKS[ri];
    const h = R.h*height*sc*(1+ (1-R.d)*.10);
    const base = nearY + R.y*height*sc;
    const c = planeCol(steelC, R.d, bp?14:6);
    const gap = (width*1.32)/Math.max(1,R.n);
    // incommensurate per-rank drift + a slow breathing term so the ranks never re-align
    const off = (pan*R.rate*width*1.4 + Math.sin(tt*(.021+ri*.0093))*width*.012*R.rate) % gap;
    for (let i2=0;i2<R.n+2;i2++){
      const idb = ri*97 + i2*13;
      const cx = -gap*.6 + i2*gap - off + (fr(idb)-.5)*gap*.30 + (P.x-.5)*width*.7;
      if (cx < -width*.45 || cx > width*1.45) continue;
      const hh = h*(.80+fr(idb+3)*.42);
      // each trolley runs its own perpetual out-and-back at an incommensurate rate
      const trR = .045 + fr(idb+5)*.075;
      const tro = .5 - .5*Math.cos((tt*trR*P.speed + fr(idb+7)*6.28));
      const gi = gantry(cx, base, hh, c, R.lw*sc, R.det, tro);
      if (R.det > .5){
        // containers massed under the backreach
        stack(cx + hh*.10, base, hh*.085*(.8+fr(idb+9)*.5), hh*.038,
              2+Math.round(fr(idb+11)*3), 2+Math.round(fr(idb+13)*3),
              planeCol([Hh+fr(idb+17)*300, sil?10:58, sil?9:34], R.d, 0), 0, idb+31);
      }
    }
    // a ship standing at the quay in the mid ranks — crosses over minutes
    if (ri===1 || ri===2){
      const sp = ((tt*(.0032+ri*.0021)*P.speed + fr(ri*23+1)) % 1.6) - .3;
      const shx = sp*width*1.3, shw = width*(.30+ri*.16)*sc, shh2 = h*(.30+ri*.10);
      const cs = planeCol([steelC[0], steelC[1]*.8, steelC[2]*1.5], R.d*.9, 5);
      noStroke(); fill(cs[0], cs[1], cs[2], 94*AL);
      rect(shx, base-shh2*.62, shw, shh2*.62);                       // hull
      rect(shx+shw*(ri===1?.06:.80), base-shh2*1.35, shw*.13, shh2*.75);  // house
      // deck-stacked boxes: the segmented band that makes the hull read as a ship
      const nbx = Math.round(7+dens*9);
      for (let q=0;q<nbx;q++){
        const bq = fr(ri*41+q*7);
        fill(Hh+bq*300, sil?8:52, cl(cs[2]*(1.05+bq*.75),0,90), 92*AL);
        rect(shx+shw*.12+q*(shw*.72/nbx), base-shh2*(.62+.28*(1+Math.floor(bq*2.4))), shw*.66/nbx, shh2*.28*(1+Math.floor(bq*2.4)));
      }
    }
  }
}

drawSteel();

// ---- the lit mass lying broken on the water --------------------------------
// mirror the steel about the waterline, dim it, then tear it into sliding bands.
push();
drawingContext.save();
drawingContext.beginPath();
drawingContext.rect(0, wy, width, height-wy);
drawingContext.clip();
drawingContext.globalAlpha = .40 + en*.16;
translate(0, 2*wy); scale(1,-1);
drawSteel();
drawingContext.restore();
pop();
// ripple bands: broad, low-alpha, always sliding -> they carry the motion floor across
// ~35% of the frame even when nothing else in the port is moving.
push();
noStroke();
const nb2 = 46;
for (let j=0;j<nb2;j++){
  const q = j/nb2, yy = wy + q*(height-wy);
  const dw = q;
  const amp = (.16+dw*.62);
  const a2 = 12*amp*(.5+.5*Math.sin(q*30 - tt*1.9 + Math.sin(q*9+tt*.61)*2.2))*(.4+hz*.9);
  fill(hazeC[0], hazeC[1]*.7, hazeC[2]*(.30+dw*.22), a2*AL);
  rect(0, yy, width, (height-wy)/nb2 + 1);
}
pop();

// ---- sodium lamps: the light source itself, glowing through the haze --------
push();
blendMode(ADD);
noStroke();
const NL2 = Math.round(9 + dens*18);
for (let i2=0;i2<NL2;i2++){
  const f1 = fr(i2*3+101), f2 = fr(i2*3+102), f3 = fr(i2*3+103);
  const rate = .16+f3*1.9;
  const lx = ((f1 + pan*rate*1.4) % 1.25 - .125)*width;
  const ly = wy - (.010 + f2*.30)*height*sc;
  // slow, shallow lamp breathing — never a strobe (amplitude <= 0.16, rates incommensurate)
  const fl = .84 + .10*Math.sin(tt*(.41+f2*.7)+f1*6.28) + .06*Math.sin(tt*(1.13+f3*.5));
  const br = (.30+en*.80)*fl;
  const rr = u*(.020+f3*.045)*(.5+hz*1.1)*(.6+en*.7)*sc;
  for (let k2=3;k2>=1;k2--){
    fill(lampC[0], lampC[1]*(.4+k2*.2), lampC[2], (bp?7:11)*br/k2*AL);
    ellipse(lx, ly, rr*k2*1.5, rr*k2*1.5);
  }
  fill(lampC[0], lampC[1]*.30, 100, 66*br*AL);
  ellipse(lx, ly, rr*.30, rr*.30);
  // its column on the water — a long vertical smear, torn by the chop
  const nsg = 9;
  for (let k2=0;k2<nsg;k2++){
    const q = k2/nsg, yy = wy + q*q*(height-wy)*.92;
    const wob = Math.sin(q*11 - tt*1.6 + f1*6.28)*u*.010*(1+q*3);
    fill(lampC[0], lampC[1]*.55, lampC[2], 15*br*(1-q*.8)*AL);
    ellipse(lx+wob, yy, rr*(.34+q*1.5), rr*(.10+q*.10));
  }
}
blendMode(BLEND);
pop();

// ---- drifting haze veils: the atmosphere the whole scene is stacked into ----
push();
noStroke();
const NV = 7;
for (let i2=0;i2<NV;i2++){
  const f1 = fr(i2*5+201), f2 = fr(i2*5+202);
  const vx = ((f1 + tt*(.0035+f2*.0075)) % 1.4 - .2)*width;
  const vyy = wy - (.02+f2*.34)*height;
  const vw = width*(.30+f1*.55), vh = height*(.035+f2*.075)*(.5+hz);
  fill(hazeC[0], hazeC[1]*.7, hazeC[2]*(.7+f2*.5), (5+hz*11)*AL);
  ellipse(vx, vyy + Math.sin(tt*(.09+f1*.14))*height*.008, vw, vh);
}
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
drawingContext.globalAlpha = 1;
